"use strict";(globalThis.webpackChunkgrc||=[]).push([[63601],{64313(e){e.exports=JSON.parse('{"citeKey":"gong2002performancemodeling","slug":"gong-2002-performance-modeling-44c0","title":"Performance Modeling and Prediction of Non-Dedicated Network Computing","authors":["L. Gong","X.-H. Sun","E. Waston"],"venue":"IEEE Trans. on Computers, Vol 51, No 9, pp. 1041-1055","type":"Journal","entryType":"article","date":"September, 2002","year":2002,"era":"iit","month":9,"doi":"10.1109/tc.2002.1032624","abstract":"The low cost and wide availability of networks of workstations have made them an attractive solution for high performance computing. However, while a network of workstations may be readily available, these workstations may be privately owned and the owners may not want others to interrupt their priority in using the computer. Assuming machine owners have a preemptive priority, in this paper, we study the parallel processing capacity of a privately owned network of workstations. A mathematical model is developed to predict performance for nondedicated network computing. It also considers systems with heterogeneous machine utilization and heterogeneous service distribution. This model separates the influence of machine utilization, sequential job service rate, and parallel task allocation on the parallel completion time. It is simple and valuable for guiding task scheduling in a nondedicated environment.","hasAbstract":true,"lede":"Assuming machine owners have a preemptive priority, in this paper, we study the parallel processing capacity of a privately owned network of workstations.","links":{"pdf":"https://grc.iit.edu/papers/2002/gong-2002-performance-modeling-44c0.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["snow"],"memberAuthors":["sun-xian-he"]}')}}]);